        try {
            r = MF.fix(paths, o);
        } catch (e) {
            rep.skipped = e.message;
            return rep;
        }
        if (r.matched) {
            rep.matched = true;
            rep.keys = idx.length;
            return rep;
        }
        for (k = 0; k < idx.length; k++) prop.setValueAtKey(idx[k], fromMF(r.paths[k]));
